<template>
  <div class="login-container">
    <div class="login-container__asside"></div>
    <div class="login-container__body">
      <div class="title-container">
        <h2>Авторизация</h2>
      </div>

      <div class="input-data">
        <v-text-field
            class="input-data__login"
            v-model="login"
            :rules="loginRules"
            hide-details="auto"
            label="Ваш логин"
            autocomplete="username"
            :disabled="isShowAuthLoader || isAuthSuccess"
        ></v-text-field>

        <div class="show-hide-password">
          <v-text-field
              class="input-data__password"
              v-model="password"
              :rules="passwordRules"
              hide-details="auto"
              label="Ваш пароль"
              autocomplete="current-password"
              :type="showPassword ? 'text' : 'password'"
              :disabled="isShowAuthLoader || isAuthSuccess"
          ></v-text-field>

          <v-icon
              v-if="showPassword"
              class="input-data__password-icon"
              @click="togglePasswordVisibility"
          >
            mdi-eye
          </v-icon>

          <v-icon
              v-if="!showPassword"
              class="input-data__password-icon"
              @click="togglePasswordVisibility"
          >
            mdi-eye-off
          </v-icon>
        </div>
      </div>

      <v-btn
          color="green-darken-1"
          :disabled="!availableConfirmBtn"
          :loading="isShowAuthLoader || isAuthSuccess"
          block
          class="confirm-btn"
          @click="checkAuth"
      >
        {{ isAuthSuccess ? 'Выполняется вход...' : 'Войти' }}
      </v-btn>
    </div>
  </div>
  <div class="text-center">
    <v-snackbar
        v-model="snackbar"
        multi-line
        timeout="3000"
        style="margin-bottom: 60px"
    >
      {{ snackbarText }}

      <template v-slot:actions>
        <v-btn
            color="red"
            variant="text"
            @click="snackbar = false"
        >
          Закрыть
        </v-btn>
      </template>
    </v-snackbar>
  </div>
  <div class="text-center">
    <v-dialog
        v-model="dialog"
        max-width="400"
        persistent
    >
      <v-card
          prepend-icon="mdi-information"
          :text="dialogText"
          :title="dialogTitle"
      >
        <template v-slot:actions>
          <v-spacer></v-spacer>

          <v-btn @click="dialog = false" color="red">
            Закрыть
          </v-btn>
        </template>
      </v-card>
    </v-dialog>
  </div>
</template>

<script>
import $ from "jquery";

export default {
  name: "LoginComponent",
  components: {},
  data() {
    return {
      dialog: false,
      login: '',
      password: '',
      loginRules: [
        value => this.validateLogin(value) || 'Требуется логин.'
      ],
      passwordRules: [
        value => this.validatePass(value) || 'Требуется пароль.'
      ],
      dialogText: '',
      dialogTitle: '',
      isShowAuthLoader: false,
      isAuthSuccess: false,
      snackbar: false,
      snackbarText: '',
      showPassword: false,
    }
  },
  computed: {
    availableConfirmBtn() {
      return (
          this.validateLogin(this.login) &&
          this.validatePass(this.password) &&
          !this.isShowAuthLoader &&
          !this.isAuthSuccess
      );
    }
  },
  methods: {
    togglePasswordVisibility() {
      if (this.isShowAuthLoader || this.isAuthSuccess) {
        return;
      }
      this.showPassword = !this.showPassword;
    },
    handleEnter(event) {
      if (event.key === 'Enter' && this.availableConfirmBtn) {
        this.checkAuth();
      }
    },
    validateLogin(value) {
      return typeof value === 'string' && value.trim().length > 0;
    },
    validatePass(value) {
      return typeof value === 'string' && value.trim().length > 0;
    },
    showDialog(title, text) {
      this.dialogTitle = title;
      this.dialogText = text;
      this.dialog = true;
    },
    normalizeRole(role) {
      return String(role || '').trim().toLowerCase();
    },
    async checkAuth() {
      if (this.isShowAuthLoader || this.isAuthSuccess || !this.availableConfirmBtn) {
        return;
      }

      this.isShowAuthLoader = true;
      this.isAuthSuccess = false;

      try {
        const response = await $.ajax({
          url: 'https://script.google.com/macros/s/AKfycbzZyyerGTUCYlCEdspNAwYkzfELY87SxYGc_ai6slWxF0zrLiFwXWZ2ewAEcoR41E3bmQ/exec',
          type: "GET",
          crossDomain: true,
          dataType: "json"
        });

        if (!response || !Array.isArray(response.stuff)) {
          throw new Error('Invalid auth response format');
        }

        const user = response.stuff.find(item => item.LoginName === this.login.trim());

        if (!user) {
          this.showDialog(
              'Сотрудник не найден',
              'Убедитесь, что вводите логин правильно'
          );
          return;
        }

        if (user.PasswordEmail !== this.password.trim()) {
          this.showDialog(
              'Неправильный пароль',
              'Убедитесь, что вводите пароль правильно'
          );
          return;
        }

        const authObj = {
          login: user.LoginName,
          role: this.normalizeRole(user.RoleStatus)
        };

        localStorage.setItem('sale-auth', JSON.stringify(authObj));

        this.isAuthSuccess = true;
        this.$emit('updateUserStatus', authObj);

      } catch (error) {
        console.error(error);
        this.snackbarText = 'Ошибка загрузки данных с сервера, повторите попытку позже';
        this.snackbar = true;
      } finally {
        if (!this.isAuthSuccess) {
          this.isShowAuthLoader = false;
        }
      }
    },
  },
  mounted() {
    document.addEventListener('keydown', this.handleEnter);
  },
  beforeUnmount() {
    document.removeEventListener('keydown', this.handleEnter);
    this.login = '';
    this.password = '';
  }
}
</script>

<style lang="scss" scoped>
.login-container {
  width: 100%;
  max-width: 750px;
  min-width: 300px;
  margin: 0 auto;
  box-shadow: 0 0 5px rgba(0, 0, 0, 0.5);
  position: relative;
  padding: 20px 45px 20px 20px;
  overflow: hidden;
  border-radius: 5px;
  background-color: snow;

  .login-container__asside {
    position: absolute;
    background-image: linear-gradient(to bottom, coral, orange, coral);
    width: 25px;
    right: 0;
    top: 0;
    bottom: 0;
    box-shadow: 0 0 3px rgba(0, 0, 0, 0.3);
  }

  .login-container__body {
    padding: 5px;

    .title-container {
      display: flex;
      flex-direction: row;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 50px;

      h2 {
        text-align: left;
        color: rgb(0 0 0 / 0.7);
        letter-spacing: 1px;
      }
    }

    .input-data {
      .v-text-field {
        background-color: white;
      }

      .input-data__login {
        margin-bottom: 20px;
      }

      .show-hide-password {
        display: flex;
        flex-direction: row;
        justify-content: center;
        align-items: center;

        .input-data__password {
        }

        .input-data__password-icon {
          margin: 10px;
          height: 100%;
        }
      }
    }

    .confirm-btn {
      margin-top: 50px;
      color: white;
    }
  }
}
</style>

<style>
.login-container input:-webkit-autofill,
.login-container input:-webkit-autofill:hover,
.login-container input:-webkit-autofill:focus,
.login-container input:-webkit-autofill:active {
  -webkit-box-shadow: 0 0 0 1000px snow inset !important;
  box-shadow: 0 0 0 1000px snow inset !important;
  -webkit-text-fill-color: #000000 !important;
  caret-color: #000000 !important;
}
</style>